# Cross-validation tests for R/kernel_pca.R against Python sklearn/scipy.
#
# Reference fixture generated by tests/generate_kernel_pca_fixture.py using
# sklearn.decomposition.KernelPCA (which internally calls scipy.linalg.eigh).


# ---------------------------------------------------------------------------
# Helper: load first 100 DASH TCRs
# ---------------------------------------------------------------------------
.load_dash_100 <- function() {
    dash_path <- test_path("fixtures", "dash.csv")
    if (!file.exists(dash_path)) return(NULL)
    dash <- read.csv(dash_path, stringsAsFactors = FALSE, nrows = 100)
    data.frame(
        va    = dash$v_a_gene,
        ja    = dash$j_a_gene,
        cdr3a = dash$cdr3_a_aa,
        vb    = dash$v_b_gene,
        jb    = dash$j_b_gene,
        cdr3b = dash$cdr3_b_aa,
        stringsAsFactors = FALSE
    )
}


# ---------------------------------------------------------------------------
# Test 1: Eigenvalues match scipy (default kernel)
# ---------------------------------------------------------------------------

test_that("eigenvalues match Python/scipy reference (default kernel)", {
    fixture_path <- test_path("fixtures", "kernel_pca_ref.json")
    skip_if_not(file.exists(fixture_path),
                "Run generate_kernel_pca_fixture.py first")
    dash_path <- test_path("fixtures", "dash.csv")
    skip_if_not(file.exists(dash_path), "dash.csv not found")
    skip_if_not_installed("jsonlite")

    ref <- jsonlite::fromJSON(fixture_path, simplifyVector = TRUE)
    tcrs <- .load_dash_100()
    skip_if(is.null(tcrs), "Could not load DASH data")

    expect_equal(nrow(tcrs), ref$n)

    result <- compute_tcrdist_kernel_pca(
        tcrs, ref$organism,
        n_components = ref$n_components,
        kernel = NULL
    )

    py_eigenvalues <- ref$default_kernel$eigenvalues

    expect_true(result$n_components >= length(py_eigenvalues),
                info = sprintf("R returned %d components, Python had %d",
                               result$n_components, length(py_eigenvalues)))

    r_eigenvalues <- result$eigenvalues[seq_along(py_eigenvalues)]
    expect_equal(r_eigenvalues, py_eigenvalues, tolerance = 1e-10,
                 label = "default kernel eigenvalues")
})


# ---------------------------------------------------------------------------
# Test 2: Embeddings match scipy (default kernel, modulo sign flip)
# ---------------------------------------------------------------------------

test_that("embeddings match Python/scipy reference (default kernel, modulo sign flip)", {
    fixture_path <- test_path("fixtures", "kernel_pca_ref.json")
    skip_if_not(file.exists(fixture_path),
                "Run generate_kernel_pca_fixture.py first")
    dash_path <- test_path("fixtures", "dash.csv")
    skip_if_not(file.exists(dash_path), "dash.csv not found")
    skip_if_not_installed("jsonlite")

    ref <- jsonlite::fromJSON(fixture_path, simplifyVector = TRUE)
    tcrs <- .load_dash_100()
    skip_if(is.null(tcrs), "Could not load DASH data")

    result <- compute_tcrdist_kernel_pca(
        tcrs, ref$organism,
        n_components = ref$n_components,
        kernel = NULL
    )

    py_embeddings <- ref$default_kernel$embeddings
    n_comp <- ncol(py_embeddings)

    for (k in seq_len(n_comp)) {
        r_col  <- result$embeddings[, k]
        py_col <- py_embeddings[, k]

        expect_equal(
            abs(r_col), abs(py_col), tolerance = 1e-8,
            info = sprintf("default kernel embedding component %d (abs values)", k)
        )

        if (sd(py_col) > 1e-12) {
            r <- cor(r_col, py_col)
            expect_true(
                abs(abs(r) - 1) < 1e-6,
                info = sprintf(
                    "default kernel component %d: |cor| = %.10f (expected ~1)",
                    k, abs(r)
                )
            )
        }
    }
})


