# ---------------------------------------------------------------------------
# Test 5: Kernel centering correctness
# ---------------------------------------------------------------------------

test_that("centered kernel has zero row and column means", {
    n <- 20
    set.seed(42)
    D <- matrix(abs(rnorm(n * n, mean = 100, sd = 50)), nrow = n, ncol = n)
    D <- (D + t(D)) / 2
    diag(D) <- 0

    Dmax <- max(D)
    K <- 1 - D / Dmax
    K[K < 0] <- 0

    K_c <- tcrdistR:::.center_kernel_matrix(K)

    expect_equal(rowMeans(K_c), rep(0, n), tolerance = 1e-12,
                 label = "centered kernel row means")
    expect_equal(colMeans(K_c), rep(0, n), tolerance = 1e-12,
                 label = "centered kernel column means")
    expect_equal(mean(K_c), 0, tolerance = 1e-14,
                 label = "centered kernel grand mean")
})


# ---------------------------------------------------------------------------
# Test 6: n_components > n reduces to n
# ---------------------------------------------------------------------------

test_that("requesting more components than TCRs returns at most n components", {
    dash_path <- test_path("fixtures", "dash.csv")
    skip_if_not(file.exists(dash_path), "dash.csv not found")

    tcrs <- .load_dash_100()
    skip_if(is.null(tcrs), "Could not load DASH data")

    result <- compute_tcrdist_kernel_pca(
        tcrs, "mouse",
        n_components = 500L,
        kernel = NULL
    )

    expect_true(result$n_components <= nrow(tcrs))
    expect_equal(nrow(result$embeddings), nrow(tcrs))
    expect_equal(ncol(result$embeddings), result$n_components)
    expect_true(all(result$eigenvalues > 0))
})


# ---------------------------------------------------------------------------
# Test 7: Small dataset works without error
# ---------------------------------------------------------------------------

test_that("small dataset (5 TCRs) works without error", {
    dash_path <- test_path("fixtures", "dash.csv")
    skip_if_not(file.exists(dash_path), "dash.csv not found")

    dash <- read.csv(dash_path, stringsAsFactors = FALSE, nrows = 5)
    tcrs <- data.frame(
        va    = dash$v_a_gene,
        cdr3a = dash$cdr3_a_aa,
        vb    = dash$v_b_gene,
        cdr3b = dash$cdr3_b_aa,
        stringsAsFactors = FALSE
    )

    result_default <- compute_tcrdist_kernel_pca(
        tcrs, "mouse", n_components = 10L, kernel = NULL
    )
    expect_true(result_default$n_components <= 5L)
    expect_equal(nrow(result_default$embeddings), 5L)
    expect_true(all(result_default$eigenvalues > 0))

    result_gaussian <- compute_tcrdist_kernel_pca(
        tcrs, "mouse", n_components = 10L, kernel = "gaussian"
    )
    expect_true(result_gaussian$n_components <= 5L)
    expect_equal(nrow(result_gaussian$embeddings), 5L)
    expect_true(all(result_gaussian$eigenvalues > 0))
})


# ---------------------------------------------------------------------------
# Test 8: RSpectra method matches eigen method
# ---------------------------------------------------------------------------

test_that("RSpectra method matches eigen method", {
    skip_if_not_installed("RSpectra")
    dash_path <- test_path("fixtures", "dash.csv")
    skip_if_not(file.exists(dash_path), "dash.csv not found")

    tcrs <- .load_dash_100()
    skip_if(is.null(tcrs), "Could not load DASH data")

    n_comp <- 20L

    result_eigen <- compute_tcrdist_kernel_pca(
        tcrs, "mouse", n_components = n_comp, method = "eigen"
    )
    result_rspectra <- compute_tcrdist_kernel_pca(
        tcrs, "mouse", n_components = n_comp, method = "RSpectra"
    )

    expect_equal(
        result_rspectra$eigenvalues[seq_len(n_comp)],
        result_eigen$eigenvalues[seq_len(n_comp)],
        tolerance = 1e-8,
        label = "RSpectra vs eigen eigenvalues"
    )

    for (k in seq_len(n_comp)) {
        r_col <- result_rspectra$embeddings[, k]
        e_col <- result_eigen$embeddings[, k]
        expect_equal(
            abs(r_col), abs(e_col), tolerance = 1e-6,
            info = sprintf("RSpectra vs eigen component %d (abs values)", k)
        )
    }
})


# ---------------------------------------------------------------------------
# Test 9: Auto method selects RSpectra when available
# ---------------------------------------------------------------------------

test_that("auto method selects RSpectra when available", {
    skip_if_not_installed("RSpectra")
    dash_path <- test_path("fixtures", "dash.csv")
    skip_if_not(file.exists(dash_path), "dash.csv not found")

    tcrs <- .load_dash_100()
    skip_if(is.null(tcrs), "Could not load DASH data")

    result_auto <- compute_tcrdist_kernel_pca(
        tcrs, "mouse", n_components = 20L, method = "auto"
    )
    result_rspectra <- compute_tcrdist_kernel_pca(
        tcrs, "mouse", n_components = 20L, method = "RSpectra"
    )

    expect_equal(result_auto$eigenvalues, result_rspectra$eigenvalues,
                 tolerance = 1e-14)
    expect_equal(result_auto$embeddings, result_rspectra$embeddings,
                 tolerance = 1e-14)
})


# ---------------------------------------------------------------------------
# Test 10: Input validation
# ---------------------------------------------------------------------------

test_that("compute_tcrdist_kernel_pca validates inputs", {
    bad_df <- data.frame(va = "x", stringsAsFactors = FALSE)
    expect_error(
        compute_tcrdist_kernel_pca(bad_df, "mouse"),
        "missing required columns"
    )

    df <- data.frame(
        va = "TRAV1*01", cdr3a = "CAVRD",
        vb = "TRBV1*01", cdr3b = "CASSI",
        stringsAsFactors = FALSE
    )
    expect_error(
        compute_tcrdist_kernel_pca(df, "mouse", kernel = "invalid"),
        "unrecognized kernel"
    )

    expect_error(
        compute_tcrdist_kernel_pca(df, "mouse", n_components = -1),
        "positive integer"
    )
})


# ---------------------------------------------------------------------------
# Test 11: Empty data.frame
# ---------------------------------------------------------------------------

test_that("empty data.frame returns empty result", {
    df <- data.frame(
        va = character(0), cdr3a = character(0),
        vb = character(0), cdr3b = character(0),
        stringsAsFactors = FALSE
    )

    result <- compute_tcrdist_kernel_pca(df, "mouse")
    expect_equal(result$n_components, 0L)
    expect_equal(nrow(result$embeddings), 0L)
    expect_equal(length(result$eigenvalues), 0L)
})


# ---------------------------------------------------------------------------
# Test 12: dist_matrix bypass
# ---------------------------------------------------------------------------

test_that("compute_tcrdist_kernel_pca accepts precomputed dist_matrix", {
    skip_on_cran()

    tcr_df <- data.frame(
        va = c("TRAV1-1*01", "TRAV1-2*01", "TRAV10*01",
               "TRAV1-1*01", "TRAV1-2*01"),
        cdr3a = c("CAVRDSSYKLIF", "CAVKDSSYKLIF", "CAVRDSYKLIF",
                   "CAVRDSSYKLIF", "CAVKDSYKLIF"),
        vb = c("TRBV5-1*01", "TRBV6-1*01", "TRBV7-2*01",
               "TRBV5-1*01", "TRBV6-1*01"),
        cdr3b = c("CASSIRSSYEQY", "CASSIKSSYEQY", "CASSIRSYEQY",
                   "CASSIRSSYEQF", "CASSIKSSYEQF"),
        stringsAsFactors = FALSE
    )

    dm <- tcrdist_matrix(tcr_df, "human")
    r1 <- compute_tcrdist_kernel_pca(tcr_df, "human", n_components = 3L)
    r2 <- compute_tcrdist_kernel_pca(dist_matrix = dm, n_components = 3L)
    expect_equal(r1$eigenvalues, r2$eigenvalues)
    expect_equal(nrow(r2$embeddings), 5L)
})
